macro_rules! deps {
    () => {
        Unicode!();
    };
}

macro_rules! is_str_bidi {
    () => {
        deps!();
        # [doc = " Checks whether a valid UTF-8 buffer contains code points that trigger"] # [doc = " right-to-left processing."] # [doc = ""] # [doc = " The check is done on a Unicode block basis without regard to assigned"] # [doc = " vs. unassigned code points in the block. Hebrew presentation forms in"] # [doc = " the Alphabetic Presentation Forms block are treated as if they formed"] # [doc = " a block on their own (i.e. it treated as right-to-left). Additionally,"] # [doc = " the four RIGHT-TO-LEFT FOO controls in General Punctuation are checked"] # [doc = " for. Control characters that are technically bidi controls but do not"] # [doc = " cause right-to-left behavior without the presence of right-to-left"] # [doc = " characters or right-to-left controls are not checked for. As a special"] # [doc = " case, U+FEFF is excluded from Arabic Presentation Forms-B."] # [allow (clippy :: collapsible_if)] # [inline] pub fn is_str_bidi (buffer : & str) -> bool { let mut bytes = buffer . as_bytes () ; 'outer : loop { if let Some ((mut byte , mut read)) = validate_ascii (bytes) { 'inner : loop { if byte < 0xE0 { if byte >= 0x80 { if unlikely (byte >= 0xD6) { if byte == 0xD6 { let second = bytes [read + 1] ; if second > 0x8F { return true ; } } else { return true ; } } read += 2 ; } else { read += 1 ; bytes = & bytes [read ..] ; continue 'outer ; } } else if byte < 0xF0 { if unlikely (! in_inclusive_range8 (byte , 0xE3 , 0xEE) && byte != 0xE1) { let second = bytes [read + 1] ; if byte == 0xE0 { if second < 0xA4 { return true ; } } else if byte == 0xE2 { let third = bytes [read + 2] ; if second == 0x80 { if third == 0x8F || third == 0xAB || third == 0xAE { return true ; } } else if second == 0x81 { if third == 0xA7 { return true ; } } } else { debug_assert_eq ! (byte , 0xEF) ; if in_inclusive_range8 (second , 0xAC , 0xB7) { if second == 0xAC { let third = bytes [read + 2] ; if third > 0x9C { return true ; } } else { return true ; } } else if in_inclusive_range8 (second , 0xB9 , 0xBB) { if second == 0xB9 { let third = bytes [read + 2] ; if third > 0xAF { return true ; } } else if second == 0xBB { let third = bytes [read + 2] ; if third != 0xBF { return true ; } } else { return true ; } } } } read += 3 ; } else { let second = bytes [read + 1] ; if unlikely (byte == 0xF0 && (second == 0x90 || second == 0x9E)) { let third = bytes [read + 2] ; if third >= 0xA0 { return true ; } } read += 4 ; } if read >= bytes . len () { return false ; } byte = bytes [read] ; continue 'inner ; } } else { return false ; } } }
    };
}

is_str_bidi!()